import 'package:flutter/material.dart';
import '../models/animal.dart';
import '../services/animal_service.dart';
import '../services/solicitacao_service.dart';
import '../widgets/async_ui.dart';
import '../widgets/foto_animal.dart';
import 'animal_form.dart';
class AnimalPage extends StatefulWidget {final String modo;const AnimalPage({super.key,required this.modo});@override State<AnimalPage> createState()=>_AnimalPageState();}
class _AnimalPageState extends State<AnimalPage>{
 final service=AnimalService();late final Stream<List<Animal>> stream;String busca='',especie='Todos',porte='Todos',idade='Todos',sexo='Todos',status='Todos';bool vac=false,cas=false;final processando=<String>{};final buscaController=TextEditingController();
 @override void dispose(){buscaController.dispose();super.dispose();}
 @override void initState(){super.initState();stream=service.listar(widget.modo);}
 String norm(String s){const a='áàâãäéèêëíìîïóòôõöúùûüç',b='aaaaaeeeeiiiiooooouuuuc';s=s.toLowerCase().trim();for(var i=0;i<a.length;i++){s=s.replaceAll(a[i],b[i]);}return s;}
 bool filtro(Animal a)=>norm(a.nome).contains(norm(busca))&&(especie=='Todos'||a.especie==especie)&&(porte=='Todos'||a.porte==porte)&&(sexo=='Todos'||a.dados['sexo']==sexo)&&(status=='Todos'||a.status==status)&&(!vac||a.dados['vacinado']==true)&&(!cas||a.dados['castrado']==true)&&(idade=='Todos'||(idade=='Filhote'&&a.idadeMeses<12)||(idade=='Jovem'&&a.idadeMeses>=12&&a.idadeMeses<36)||(idade=='Adulto'&&a.idadeMeses>=36&&a.idadeMeses<84)||(idade=='Idoso'&&a.idadeMeses>=84));
 Widget seletor(String label,String value,List<String> itens,void Function(String) f)=>DropdownButton<String>(value:value,items:itens.map((v)=>DropdownMenuItem(value:v,child:Text('$label: $v'))).toList(),onChanged:(v)=>setState(()=>f(v!)));
 Future<void> acao(Animal a,Future<void> Function() fn) async {if(processando.contains(a.id)||!await confirmar(context,'Confirmar operação para ${a.nome}?')||!mounted)return;setState(()=>processando.add(a.id));await executar(context,fn);if(mounted)setState(()=>processando.remove(a.id));}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.modo=='catalogo'?'Animais para adoção':widget.modo=='meus'?'Meus animais':'Gerenciar animais')),floatingActionButton:widget.modo=='meus'?FloatingActionButton(onPressed:()=>abrir(context,const AnimalForm()),child:const Icon(Icons.add)):null,body:StreamBuilder<List<Animal>>(stream:stream,builder:(context,s){if(s.hasError)return erro(s.error);if(!s.hasData)return espera();final lista=s.data!.where(filtro).toList();return CustomScrollView(slivers:[SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.all(12),child:Column(children:[TextField(controller:buscaController,decoration:const InputDecoration(labelText:'Buscar nome'),onChanged:(v)=>setState(()=>busca=v)),Wrap(spacing:12,children:[seletor('Espécie',especie,['Todos','Cachorro','Gato','Outro'],(v)=>especie=v),seletor('Porte',porte,['Todos','Pequeno','Médio','Grande'],(v)=>porte=v),seletor('Idade',idade,['Todos','Filhote','Jovem','Adulto','Idoso'],(v)=>idade=v),seletor('Sexo',sexo,['Todos','Macho','Fêmea'],(v)=>sexo=v),if(widget.modo!='catalogo')seletor('Status',status,['Todos','pendente','disponivel','reprovado','em_adocao','adotado'],(v)=>status=v)]),CheckboxListTile(title:const Text('Somente vacinados'),value:vac,onChanged:(v)=>setState(()=>vac=v!)),CheckboxListTile(title:const Text('Somente castrados'),value:cas,onChanged:(v)=>setState(()=>cas=v!)),TextButton(onPressed:()=>setState((){buscaController.clear();busca='';especie=porte=idade=sexo=status='Todos';vac=cas=false;}),child:const Text('Limpar filtros')),Text('${lista.length} animais encontrados')]))),SliverList(delegate:SliverChildBuilderDelegate((context,i){final a=lista[i];final editavel=['pendente','disponivel','reprovado'].contains(a.status);final livre=!processando.contains(a.id);return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[FotoAnimal(fotoBase64:a.fotoBase64),Text(a.nome,style:Theme.of(context).textTheme.titleLarge),Text('${a.especie} • ${a.idadeMeses} meses • ${a.porte}'),Text(a.status),Wrap(children:[TextButton(onPressed:()=>abrir(context,AnimalDetalhes(animal:a,podeSolicitar:widget.modo=='catalogo'&&a.doadorId!=service.uid)),child:const Text('Detalhes')),if(widget.modo=='meus'&&editavel)TextButton(onPressed:livre?()=>abrir(context,AnimalForm(animal:a)):null,child:const Text('Editar')),if(widget.modo!='catalogo'&&editavel)TextButton(onPressed:livre?()=>acao(a,()=>service.excluir(a.id)):null,child:const Text('Excluir')),if(widget.modo=='admin'&&a.status=='pendente')TextButton(onPressed:livre?()=>acao(a,()=>service.moderar(a.id,'disponivel')):null,child:const Text('Aprovar')),if(widget.modo=='admin'&&['pendente','disponivel'].contains(a.status))TextButton(onPressed:livre?()=>acao(a,()=>service.moderar(a.id,'reprovado')):null,child:const Text('Reprovar/retirar'))])])));},childCount:lista.length))]);}));
}
class AnimalDetalhes extends StatefulWidget {final Animal animal;final bool podeSolicitar;const AnimalDetalhes({super.key,required this.animal,required this.podeSolicitar});@override State<AnimalDetalhes> createState()=>_AnimalDetalhesState();}
class _AnimalDetalhesState extends State<AnimalDetalhes>{final mensagem=TextEditingController();bool ocupado=false;@override void dispose(){mensagem.dispose();super.dispose();}
 @override Widget build(BuildContext context){final a=widget.animal;return Scaffold(appBar:AppBar(title:Text(a.nome)),body:ListView(padding:const EdgeInsets.all(16),children:[FotoAnimal(fotoBase64:a.fotoBase64,altura:280),for(final k in ['nome','especie','raca','idadeMeses','porte','sexo','descricao','status'])Text('$k: ${a.dados[k]}'),Text('Vacinado: ${a.dados['vacinado']==true?'Sim':'Não'}'),Text('Castrado: ${a.dados['castrado']==true?'Sim':'Não'}'),if(widget.podeSolicitar)...[const SizedBox(height:16),TextField(controller:mensagem,maxLength:1000,maxLines:4,decoration:const InputDecoration(labelText:'Por que deseja adotar?')),FilledButton(onPressed:ocupado?null:() async {if(mensagem.text.trim().isEmpty)return;setState(()=>ocupado=true);await executar(context,()async{await SolicitacaoService().solicitar(a.id,mensagem.text);mensagem.clear();});if(mounted)setState(()=>ocupado=false);},child:const Text('Solicitar adoção'))]]));}
}
